import React from 'react';
import { Dialog, DialogContent, IconButton, Box } from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import photo from '../../public/photo.png'
interface ImagePreviewModalProps {
  open: boolean;
  imageSrc: string;
  onClose: () => void;
}

const ImagePreviewModal: React.FC<ImagePreviewModalProps> = ({ open, imageSrc, onClose }) => {
  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="lg"
      fullWidth
      sx={{
        '& .MuiDialog-paper': {
          backgroundColor: '#000',
          borderRadius: 2,
        },
      }}
    >
      {/* ปุ่มปิด */}
      <IconButton
        onClick={onClose}
        sx={{
          position: 'absolute',
          top: 8,
          right: 8,
          color: '#fff',
          backgroundColor: 'rgba(0,0,0,0.5)',
          '&:hover': { backgroundColor: 'rgba(0,0,0,0.7)' },
        }}
      >
        <CloseIcon />
      </IconButton>

      {/* แสดงภาพ */}
      <DialogContent sx={{ p: 0, display: 'flex', justifyContent: 'center' }}>
        <Box
          component="img"
          src={imageSrc ?? '/photo.png'}
          alt="Preview"
          sx={{
            maxWidth: '100%',
            maxHeight: '80vh',
            borderRadius: 2,
            objectFit: 'contain',
          }}
        />
      </DialogContent>
    </Dialog>
  );
};

export default ImagePreviewModal;
